<?php namespace backend\models; use yii\base\Model; use yii\data\ActiveDataProvider; class GradeElementSearch extends GradeElement { public function rules(){return [[['code','name','short_name'],'safe']];} public function scenarios(){return Model::scenarios();} public function search($params){$q=GradeElement::find();$p=new ActiveDataProvider(['query'=>$q]);$this->load($params);if($this->validate())$q->andFilterWhere(['like','code',$this->code])->andFilterWhere(['like','name',$this->name])->andFilterWhere(['like','short_name',$this->short_name]);return $p;}}
